sysauto_script.script:
// SpokePulse — IntegrationHub Spoke & Connection Health Monitor
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// Scheduled daily scan: run the full scan, then alert on high-risk findings.
(function () {
    try {
        var engine = new SpokePulseEngine();
        var summary = engine.runAndSummarize('scheduled');
        var alert = engine.alertHighRisk(summary.run_id);
        gs.info('SpokePulse daily scan complete: ' + summary.total_items +
            ' items, ' + summary.distribution.broken + ' broken, ' +
            summary.distribution['at-risk'] + ' at-risk.');
    } catch (e) {
        gs.error('SpokePulse daily scan failed: ' + e.message);
    }
})();
